package verify;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.mockito.Mockito.when;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.context.bean.override.mockito.MockitoBean;

@SpringBootTest(classes = GreeterApp.class)
class GreeterTest {

    // Replaces the real Greeter bean in the context with a Mockito mock.
    // (Spring Boot 4 removed @MockBean; @MockitoBean is its replacement.)
    @MockitoBean
    Greeter greeterMock;

    @Autowired
    Greeter greeter;

    @Test
    void autowiredGreeterIsMockedAndReturnsStub() {
        when(greeterMock.greet()).thenReturn("mock");

        assertEquals("mock", greeter.greet());
    }
}

